/* The Lua side of the runtime shared by every module generated by
 * uniffi-bindgen-lua. Header-only (`static inline`), on top of uniffi_runtime.h.
 *
 * Works with Lua 5.1 (and LuaJIT) through 5.5. On 5.1 numbers are doubles, so
 * 64-bit integers beyond 2^53 lose precision there.
 *
 * Lua states are not thread-safe, and Rust may call a callback on any thread.
 * Callbacks on the thread that loaded the module run at once; callbacks from
 * other threads are queued and run on that thread: in `<module>.poll()`, at the
 * start of every call into the module, and while a call waits for an async
 * result. A callback that returns nothing does not make Rust wait for it.
 */
#ifndef UNIFFI_BINDGEN_LUA_RUNTIME_H
#define UNIFFI_BINDGEN_LUA_RUNTIME_H

#include "uniffi_runtime.h"

#include <lauxlib.h>
#include <lua.h>

/* ---- Compatibility with Lua 5.1 / LuaJIT ---- */

#if LUA_VERSION_NUM < 502
#define lua_rawlen lua_objlen
static inline void uniffi_lua_setfuncs(lua_State *L, const luaL_Reg *l) {
    for (; l->name != NULL; l++) {
        lua_pushcfunction(L, l->func);
        lua_setfield(L, -2, l->name);
    }
}
static inline void *uniffi_lua_testudata(lua_State *L, int idx, const char *tname) {
    void *p = lua_touserdata(L, idx);
    if (p == NULL || !lua_getmetatable(L, idx)) {
        return NULL;
    }
    luaL_getmetatable(L, tname);
    int same = lua_rawequal(L, -1, -2);
    lua_pop(L, 2);
    return same ? p : NULL;
}
#define LUA_OK 0
#else
#define uniffi_lua_setfuncs(L, l) luaL_setfuncs(L, l, 0)
#define uniffi_lua_testudata luaL_testudata
#endif

#if LUA_VERSION_NUM < 503
static inline int uniffi_lua_isinteger(lua_State *L, int idx) {
    if (lua_type(L, idx) != LUA_TNUMBER) {
        return 0;
    }
    lua_Number n = lua_tonumber(L, idx);
    return n == (lua_Number)(int64_t)n;
}
#else
#define uniffi_lua_isinteger lua_isinteger
#endif

#if LUA_VERSION_NUM < 504
#define uniffi_lua_newuserdata(L, size) lua_newuserdata(L, size)
#else
#define uniffi_lua_newuserdata(L, size) lua_newuserdatauv(L, size, 1)
#endif

/* ---- Numbers ---- */

static inline int64_t uniffi_lua_check_i64(lua_State *L, int idx) {
#if LUA_VERSION_NUM >= 503
    return (int64_t)luaL_checkinteger(L, idx);
#else
    if (!uniffi_lua_isinteger(L, idx)) {
        luaL_argerror(L, idx, "an integer expected");
    }
    return (int64_t)lua_tonumber(L, idx);
#endif
}

/** An integer of `bits` bits, signed or not; raises when out of range. */
static inline int64_t uniffi_lua_check_int(lua_State *L, int idx, int bits, bool is_signed, const char *what) {
    int64_t v = uniffi_lua_check_i64(L, idx);
    if (bits < 64) {
        int64_t lo = is_signed ? -((int64_t)1 << (bits - 1)) : 0;
        int64_t hi = is_signed ? ((int64_t)1 << (bits - 1)) - 1 : ((int64_t)1 << bits) - 1;
        if (v < lo || v > hi) {
            /* Lua 5.1's luaL_error knows no %lld. */
            char number[32];
            snprintf(number, sizeof number, "%lld", (long long)v);
            luaL_error(L, "%s: %s is out of range", what, number);
        }
    } else if (!is_signed && v < 0) {
#if LUA_VERSION_NUM < 503
        luaL_error(L, "%s: a negative number for an unsigned integer", what);
#endif
        /* 5.3+: integers wrap, so u64 above 2^63 arrive negative (as math.ult expects). */
    }
    return v;
}

static inline void uniffi_lua_push_u64(lua_State *L, uint64_t v) {
#if LUA_VERSION_NUM >= 503
    lua_pushinteger(L, (lua_Integer)v);
#else
    lua_pushnumber(L, (lua_Number)v);
#endif
}

static inline void uniffi_lua_push_i64(lua_State *L, int64_t v) {
#if LUA_VERSION_NUM >= 503
    lua_pushinteger(L, (lua_Integer)v);
#else
    lua_pushnumber(L, (lua_Number)v);
#endif
}

static inline bool uniffi_lua_check_bool(lua_State *L, int idx, const char *what) {
    if (!lua_isboolean(L, idx)) {
        luaL_error(L, "%s: a boolean expected, got %s", what, luaL_typename(L, idx));
    }
    return lua_toboolean(L, idx) != 0;
}

static inline double uniffi_lua_check_number(lua_State *L, int idx, const char *what) {
    if (lua_type(L, idx) != LUA_TNUMBER) {
        luaL_error(L, "%s: a number expected, got %s", what, luaL_typename(L, idx));
    }
    return (double)lua_tonumber(L, idx);
}

static inline const char *uniffi_lua_check_lstring(lua_State *L, int idx, size_t *len, const char *what) {
    if (lua_type(L, idx) != LUA_TSTRING) {
        luaL_error(L, "%s: a string expected, got %s", what, luaL_typename(L, idx));
    }
    return lua_tolstring(L, idx, len);
}

/* ---- A writer owned by the Lua GC: an argument check may raise mid-call ---- */

static inline int uniffi_lua_writer_gc(lua_State *L) {
    uniffi_writer *w = (uniffi_writer *)lua_touserdata(L, 1);
    uniffi_writer_free(w);
    return 0;
}

/** A writer whose memory the Lua GC frees if a `lua_error` skips the explicit free. */
static inline uniffi_writer *uniffi_lua_writer(lua_State *L) {
    uniffi_writer *w = (uniffi_writer *)uniffi_lua_newuserdata(L, sizeof *w);
    w->data = NULL;
    w->len = w->cap = 0;
    if (luaL_newmetatable(L, "uniffi.writer")) {
        lua_pushcfunction(L, uniffi_lua_writer_gc);
        lua_setfield(L, -2, "__gc");
    }
    lua_setmetatable(L, -2);
    lua_pop(L, 1); /* reachable from nowhere: collected after the call */
    return w;
}

/* ---- Running callbacks on the Lua thread ---- */

#if defined(_WIN32)
typedef DWORD uniffi_thread_id;
static inline uniffi_thread_id uniffi_current_thread(void) { return GetCurrentThreadId(); }
static inline bool uniffi_same_thread(uniffi_thread_id a, uniffi_thread_id b) { return a == b; }
#else
typedef pthread_t uniffi_thread_id;
static inline uniffi_thread_id uniffi_current_thread(void) { return pthread_self(); }
static inline bool uniffi_same_thread(uniffi_thread_id a, uniffi_thread_id b) { return pthread_equal(a, b) != 0; }
#endif

typedef struct uniffi_lua_job {
    void (*run)(lua_State *L, void *arg);
    void *arg;
    /* Waited on by the posting thread; jobs nobody waits for free themselves. */
    bool waited;
    bool done;
    struct uniffi_lua_job *next;
} uniffi_lua_job;

typedef struct uniffi_lua_dispatcher {
    uniffi_mutex mutex;
    uniffi_cond cond;
    uniffi_lua_job *head;
    uniffi_lua_job *tail;
    lua_State *L;
    uniffi_thread_id owner;
} uniffi_lua_dispatcher;

static inline void uniffi_lua_dispatcher_init(uniffi_lua_dispatcher *d, lua_State *L) {
    uniffi_mutex_init(&d->mutex);
    uniffi_cond_init(&d->cond);
    d->head = d->tail = NULL;
    d->L = L;
    d->owner = uniffi_current_thread();
}

/* Bump with any change to the dispatcher or job layout: modules built with another
 * layout must not share one. */
#define UNIFFI_LUA_DISPATCHER_KEY "uniffi_lua.dispatcher.v1"

/** The dispatcher of `L`, shared by every module loaded into it: a call that waits in
 *  one module (an async call, `poll()`) also runs the callbacks Rust makes into the
 *  others, which would otherwise wait for a call into their own module and block the
 *  Rust thread making them (a broker's auth callback during a client's connect).
 *  Created by the first module; never freed, as Rust threads may still post to it
 *  after the state is closed. */
static inline uniffi_lua_dispatcher *uniffi_lua_shared_dispatcher(lua_State *L) {
    lua_getfield(L, LUA_REGISTRYINDEX, UNIFFI_LUA_DISPATCHER_KEY);
    uniffi_lua_dispatcher *d = (uniffi_lua_dispatcher *)lua_touserdata(L, -1);
    lua_pop(L, 1);
    if (d == NULL) {
        d = (uniffi_lua_dispatcher *)uniffi_alloc(sizeof *d);
        uniffi_lua_dispatcher_init(d, L);
        lua_pushlightuserdata(L, d);
        lua_setfield(L, LUA_REGISTRYINDEX, UNIFFI_LUA_DISPATCHER_KEY);
    }
    return d;
}

static inline bool uniffi_lua_on_owner(uniffi_lua_dispatcher *d) {
    return uniffi_same_thread(uniffi_current_thread(), d->owner);
}

/** Runs the queued callbacks. Only on the owner thread. */
static inline void uniffi_lua_service(uniffi_lua_dispatcher *d) {
    for (;;) {
        uniffi_mutex_lock(&d->mutex);
        uniffi_lua_job *job = d->head;
        if (job) {
            d->head = job->next;
            if (!d->head) {
                d->tail = NULL;
            }
        }
        uniffi_mutex_unlock(&d->mutex);
        if (!job) {
            return;
        }
        job->run(d->L, job->arg);
        if (job->waited) {
            uniffi_mutex_lock(&d->mutex);
            job->done = true;
            uniffi_cond_signal(&d->cond);
            uniffi_mutex_unlock(&d->mutex);
        } else {
            free(job);
        }
    }
}

/** Runs `run(L, arg)` on the Lua thread: now when this is it, else queued; waits
 *  for it unless `detach` (then `run` must own and free `arg`). */
static inline void uniffi_lua_invoke(uniffi_lua_dispatcher *d, void (*run)(lua_State *, void *), void *arg, bool detach) {
    if (uniffi_lua_on_owner(d)) {
        run(d->L, arg);
        return;
    }
    uniffi_lua_job *job = (uniffi_lua_job *)uniffi_alloc(sizeof *job);
    job->run = run;
    job->arg = arg;
    job->waited = !detach;
    job->done = false;
    job->next = NULL;
    uniffi_mutex_lock(&d->mutex);
    if (d->tail) {
        d->tail->next = job;
    } else {
        d->head = job;
    }
    d->tail = job;
    uniffi_cond_signal(&d->cond);
    if (!detach) {
        while (!job->done) {
            uniffi_cond_wait(&d->cond, &d->mutex);
        }
        uniffi_mutex_unlock(&d->mutex);
        free(job);
        return;
    }
    uniffi_mutex_unlock(&d->mutex);
}

/* A Rust future being waited for by the Lua thread. */
typedef struct uniffi_lua_waiter {
    uniffi_lua_dispatcher *d;
    bool woken;
    int8_t poll_result;
} uniffi_lua_waiter;

static inline void uniffi_lua_continuation(uint64_t data, int8_t poll_result) {
    uniffi_lua_waiter *w = (uniffi_lua_waiter *)(uintptr_t)data;
    uniffi_mutex_lock(&w->d->mutex);
    w->poll_result = poll_result;
    w->woken = true;
    uniffi_cond_signal(&w->d->cond);
    uniffi_mutex_unlock(&w->d->mutex);
}

/** Polls `future` until ready, running queued callbacks meanwhile. */
static inline void uniffi_lua_block_on(uniffi_lua_dispatcher *d, uint64_t future, uniffi_poll_fn poll) {
    uniffi_lua_waiter w;
    w.d = d;
    for (;;) {
        w.woken = false;
        poll(future, uniffi_lua_continuation, (uint64_t)(uintptr_t)&w);
        for (;;) {
            uniffi_lua_service(d);
            uniffi_mutex_lock(&d->mutex);
            if (w.woken) {
                uniffi_mutex_unlock(&d->mutex);
                break;
            }
            if (!d->head) {
                uniffi_cond_wait(&d->cond, &d->mutex);
            }
            uniffi_mutex_unlock(&d->mutex);
        }
        if (w.poll_result == UNIFFI_RUST_FUTURE_POLL_READY) {
            return;
        }
    }
}

/* ---- Strings, times, error messages ---- */

/** Pushes the length-prefixed string at the reader's position, without a copy. */
static inline void uniffi_lua_push_wire_string(lua_State *L, uniffi_reader *r) {
    size_t n = uniffi_read_len(r, 1);
    if (r->failed) {
        lua_pushnil(L);
        return;
    }
    lua_pushlstring(L, (const char *)r->data + r->pos, n);
    r->pos += n;
}

/** A timestamp from seconds since the Unix epoch (fractions allowed, negative before 1970). */
static inline uniffi_timestamp uniffi_lua_seconds_to_timestamp(double seconds) {
    double whole = seconds >= 0 ? (double)(int64_t)seconds : -(double)(int64_t)(-seconds);
    if (whole > seconds) {
        whole -= 1.0;
    }
    uniffi_timestamp t;
    t.secs = (int64_t)whole;
    double nanos = (seconds - whole) * 1e9 + 0.5;
    t.nanos = nanos >= 1e9 ? 999999999u : (uint32_t)nanos;
    return t;
}

static inline uniffi_duration uniffi_lua_seconds_to_duration(lua_State *L, double seconds, const char *what) {
    if (seconds < 0) {
        luaL_error(L, "%s: a duration cannot be negative", what);
    }
    uniffi_duration d;
    d.secs = (uint64_t)seconds;
    double nanos = (seconds - (double)d.secs) * 1e9 + 0.5;
    d.nanos = nanos >= 1e9 ? 999999999u : (uint32_t)nanos;
    return d;
}

static inline void uniffi_lua_push_timestamp(lua_State *L, uniffi_timestamp t) {
    lua_pushnumber(L, (lua_Number)t.secs + (lua_Number)t.nanos / 1e9);
}

static inline void uniffi_lua_push_duration(lua_State *L, uniffi_duration d) {
    lua_pushnumber(L, (lua_Number)d.secs + (lua_Number)d.nanos / 1e9);
}

/** A printable form of the error value at `idx` (its `__tostring`, else its type). */
static inline const char *uniffi_lua_error_message(lua_State *L, int idx, size_t *len) {
    if (lua_type(L, idx) == LUA_TSTRING || lua_type(L, idx) == LUA_TNUMBER) {
        return lua_tolstring(L, idx, len);
    }
    if (luaL_callmeta(L, idx, "__tostring") && lua_type(L, -1) == LUA_TSTRING) {
        return lua_tolstring(L, -1, len);
    }
    lua_pushfstring(L, "(a %s error value)", luaL_typename(L, idx));
    return lua_tolstring(L, -1, len);
}

#if LUA_VERSION_NUM < 502
#define uniffi_lua_absindex(L, i) ((i) > 0 || (i) <= LUA_REGISTRYINDEX ? (i) : lua_gettop(L) + (i) + 1)
#else
#define uniffi_lua_absindex lua_absindex
#endif

/** `__tostring` of an error table: "Variant" or "Variant: message". */
static inline int uniffi_lua_error_tostring(lua_State *L) {
    lua_getfield(L, 1, "tag");
    lua_getfield(L, 1, "message");
    if (lua_isstring(L, -1)) {
        lua_pushfstring(L, "%s: %s", lua_tostring(L, -2), lua_tostring(L, -1));
    } else {
        lua_pushfstring(L, "%s", lua_tostring(L, -2) ? lua_tostring(L, -2) : "error");
    }
    return 1;
}

#endif /* UNIFFI_BINDGEN_LUA_RUNTIME_H */
